create or replace function glf_kyc_private.fields() returns jsonb language sql immutable set search_path='' as $fields$ select '[{"key":"relation","label":["¿Cuál es su vínculo con GLF?","What is your relationship with GLF?"],"step":0,"required":true,"type":"select","options":["supplier","consultant","staff","board"],"help":["Primero confirme el vínculo indicado por Carolina. Equipo y Directorio no se incorporan al directorio de proveedores.","Confirm the relationship selected by Carolina. Staff and board members are not added to the supplier directory."]},{"key":"nationalityType","label":["Condición de la contratación","Engagement location"],"step":0,"required":true,"type":"select","when":{"relation":["supplier","consultant"]},"options":["national","international"]},{"key":"person","label":["¿En nombre de quién presenta el formulario?","On whose behalf are you completing this form?"],"step":0,"required":true,"type":"select","when":{"relation":["supplier","consultant"]},"options":["natural","legal"],"help":["Tener RUC no convierte a una persona natural en compañía. Seleccione persona jurídica solo si contrata la entidad.","A tax ID does not make an individual a company. Select legal entity only when the entity is the contracting party."]},{"key":"country","label":["País de emisión o constitución","Country of issue / incorporation"],"step":1,"required":true,"type":"country"},{"key":"idType","label":["Tipo de identificación","Identification type"],"step":1,"required":true,"type":"document"},{"key":"id","label":["Número de identificación","Identification number"],"step":1,"required":true,"type":"text","max":60},{"key":"name","label":["Nombre completo / razón social","Full name / registered name"],"step":1,"required":true,"type":"text"},{"key":"birthDate","label":["Fecha de nacimiento","Date of birth"],"step":1,"required":true,"type":"date","when":{"person":["natural"]}},{"key":"incorporationDate","label":["Fecha de constitución","Date of incorporation"],"step":1,"required":true,"type":"date","when":{"person":["legal"]}},{"key":"nationality","label":["Nacionalidad","Nationality"],"step":1,"required":true,"type":"text","when":{"person":["natural"]}},{"key":"email","label":["Correo electrónico","Email"],"step":1,"required":true,"type":"email"},{"key":"phone","label":["Teléfono","Phone"],"step":1,"required":true,"type":"tel","max":50},{"key":"residenceCountry","label":["País de domicilio","Country of residence"],"step":1,"required":true,"type":"country"},{"key":"city","label":["Ciudad de domicilio","City of residence"],"step":1,"required":true,"type":"text"},{"key":"address","label":["Dirección de domicilio","Residential / registered address"],"step":1,"required":true,"type":"text","max":1000},{"key":"invoice","label":["¿Facturará al GLF?","Will you invoice GLF?"],"step":2,"required":true,"type":"select","when":{"relation":["supplier","consultant"],"person":["natural"],"idType":["cedula","passport","foreign_id"]},"options":["yes","no"]},{"key":"taxId","label":["RUC / identificación tributaria adicional","Additional RUC / tax ID"],"step":2,"required":true,"type":"text","when":{"relation":["supplier","consultant"],"person":["natural"],"idType":["cedula","passport","foreign_id"],"invoice":["yes"]},"max":60,"help":["Se registra para facturación; no activa preguntas sobre una compañía.","Recorded for invoicing; it does not activate company questions."]},{"key":"activity","label":["Actividad económica o profesional","Economic or professional activity"],"step":2,"required":true,"type":"textarea","when":{"relation":["supplier","consultant"]},"max":2000},{"key":"services","label":["Bienes o servicios que prestará al GLF","Goods or services you will provide to GLF"],"step":2,"required":true,"type":"textarea","when":{"relation":["supplier","consultant"]},"max":2000},{"key":"website","label":["Sitio web (opcional)","Website (optional)"],"step":2,"required":false,"type":"text","when":{"relation":["supplier","consultant"]}},{"key":"monthlyIncome","label":["Ingresos mensuales estimados (USD)","Estimated monthly income (USD)"],"step":2,"required":true,"type":"number","when":{"relation":["supplier","consultant"]}},{"key":"monthlyExpenses","label":["Egresos mensuales estimados (USD)","Estimated monthly expenses (USD)"],"step":2,"required":true,"type":"number","when":{"relation":["supplier","consultant"]}},{"key":"bankName","label":["Entidad bancaria","Bank name"],"step":2,"required":true,"type":"text","when":{"relation":["supplier","consultant"]}},{"key":"bankHolder","label":["Titular de la cuenta","Account holder"],"step":2,"required":true,"type":"text","when":{"relation":["supplier","consultant"]}},{"key":"bankAccount","label":["Número de cuenta / IBAN","Account number / IBAN"],"step":2,"required":true,"type":"text","when":{"relation":["supplier","consultant"]},"max":100},{"key":"role","label":["Cargo o función en GLF","Position or role at GLF"],"step":2,"required":true,"type":"text","when":{"relation":["staff","board"]}},{"key":"employer","label":["Entidad empleadora / ocupación actual","Current employer / occupation"],"step":2,"required":false,"type":"text","when":{"relation":["staff","board"]}},{"key":"legalRep","label":["Nombre del representante legal","Legal representative name"],"step":3,"required":true,"type":"text","when":{"person":["legal"]}},{"key":"legalRepId","label":["Identificación del representante","Representative identification"],"step":3,"required":true,"type":"text","when":{"person":["legal"]},"max":60},{"key":"legalRepCountry","label":["País de emisión del documento del representante","Representative ID issuing country"],"step":3,"required":true,"type":"country","when":{"person":["legal"]}},{"key":"ownershipExplanation","label":["Si no existen socios declarables, explique la estructura","If there are no reportable owners, explain the structure"],"step":3,"required":false,"type":"textarea","when":{"person":["legal"]},"max":2000},{"key":"controllers","label":["Personas con control sin participación (si corresponde; para revisión)","Persons with control without ownership (if applicable; for review)"],"step":3,"required":false,"type":"textarea","when":{"person":["legal"]},"max":2000,"help":["La obligación documental de estas personas está pendiente de validación por Carolina.","Document requirements for these persons remain subject to Carolina’s confirmation."]},{"key":"spouse","label":["¿Tiene cónyuge o pareja registrada?","Do you have a spouse or registered partner?"],"step":3,"required":true,"type":"select","when":{"person":["natural"]},"options":["yes","no"]},{"key":"spouseName","label":["Nombre del cónyuge o pareja","Spouse / partner name"],"step":3,"required":true,"type":"text","when":{"person":["natural"],"spouse":["yes"]}},{"key":"spouseId","label":["Identificación del cónyuge o pareja","Spouse / partner identification"],"step":3,"required":true,"type":"text","when":{"person":["natural"],"spouse":["yes"]},"max":60},{"key":"pepSelf","label":["¿El declarante o representante desempeña o desempeñó una función pública relevante (PEP)?","Does or did the applicant or representative hold a prominent public function (PEP)?"],"step":4,"required":true,"type":"select","options":["yes","no"]},{"key":"pepSelfPosition","label":["Cargo público","Public position"],"step":4,"required":true,"type":"text","when":{"pepSelf":["yes"]}},{"key":"pepSelfInstitution","label":["Institución pública","Public institution"],"step":4,"required":true,"type":"text","when":{"pepSelf":["yes"]}},{"key":"pepSelfCountry","label":["País del cargo público","Country of public position"],"step":4,"required":true,"type":"country","when":{"pepSelf":["yes"]}},{"key":"pepFamily","label":["¿Tiene un familiar PEP?","Do you have a family member who is a PEP?"],"step":4,"required":true,"type":"select","options":["yes","no"]},{"key":"pepName","label":["Nombre del familiar PEP","PEP family member name"],"step":4,"required":true,"type":"text","when":{"pepFamily":["yes"]}},{"key":"pepRelation","label":["Parentesco","Family relationship"],"step":4,"required":true,"type":"text","when":{"pepFamily":["yes"]}},{"key":"pepPosition","label":["Cargo del familiar PEP","PEP family member position"],"step":4,"required":true,"type":"text","when":{"pepFamily":["yes"]}},{"key":"pepInstitution","label":["Institución del familiar PEP","PEP family member institution"],"step":4,"required":true,"type":"text","when":{"pepFamily":["yes"]}},{"key":"pepCountry","label":["País del familiar PEP","PEP family member country"],"step":4,"required":true,"type":"country","when":{"pepFamily":["yes"]}},{"key":"glfFamily","label":["¿Tiene familiares que trabajen o integren el GLF?","Do you have relatives working for or serving on GLF?"],"step":4,"required":true,"type":"select","options":["yes","no"]},{"key":"glfFamilyDetail","label":["Nombre, parentesco y función en GLF","Name, relationship and GLF role"],"step":4,"required":true,"type":"textarea","when":{"glfFamily":["yes"]},"max":2000},{"key":"funds","label":["Origen lícito de los recursos / explicación de la actividad","Lawful source of funds / explanation of activity"],"step":4,"required":true,"type":"textarea","when":{"relation":["supplier","consultant"]},"max":2000},{"key":"truth","label":["Confirmo que la información es completa y veraz para este expediente de prueba","I confirm that the information is complete and accurate for this test case"],"step":4,"required":true,"type":"select","options":["yes"]}]'::jsonb $fields$;
create or replace function glf_kyc_private.applies(f jsonb,a jsonb) returns boolean language sql immutable set search_path='' as $$
 select not exists(select 1 from jsonb_each(coalesce(f->'when','{}')) w where not coalesce(w.value ? (a->>w.key),false));
$$;
create or replace function glf_kyc_private.project(p jsonb) returns jsonb language plpgsql immutable set search_path='' as $$
declare a jsonb:=p;r jsonb:='{}';f jsonb;o jsonb;owners jsonb:='[]';
begin
 if a->>'relation' in('staff','board') then a=jsonb_set(a,'{person}','"natural"');end if;
 if a->>'person'='legal' then a=jsonb_set(a,'{idType}',to_jsonb(case when a->>'country'='EC' then 'ruc' else 'tax_id' end));
 elsif a->>'country'='EC' then if a->>'relation' in('staff','board') or coalesce(a->>'idType','') not in('cedula','ruc') then a=jsonb_set(a,'{idType}','"cedula"');end if;elsif coalesce(a->>'idType','') not in('passport','foreign_id') then a=jsonb_set(a,'{idType}','"passport"');end if;
 for f in select value from jsonb_array_elements(glf_kyc_private.fields()) loop
 if glf_kyc_private.applies(f,a) then r=r||jsonb_build_object(f->>'key',trim(coalesce(a->>(f->>'key'),'')));end if;end loop;
 if a->>'person'='legal' and jsonb_typeof(a->'owners')='array' then
 for o in select value from jsonb_array_elements(a->'owners') limit 30 loop owners=owners||jsonb_build_array(jsonb_build_object('name',trim(coalesce(o->>'name','')),'pct',coalesce(o->>'pct',''),'country',trim(coalesce(o->>'country','')),'id',trim(coalesce(o->>'id',''))));end loop;end if;
 return r||jsonb_build_object('person',coalesce(a->>'person',''),'owners',owners);
end;$$;
create or replace function glf_kyc_private.validate(p jsonb) returns text[] language plpgsql stable set search_path='' as $$
declare a jsonb:=glf_kyc_private.project(p);f jsonb;v text;errs text[]:='{}';o jsonb;total numeric:=0;
begin
 for f in select value from jsonb_array_elements(glf_kyc_private.fields()) loop
 if not glf_kyc_private.applies(f,a) then continue;end if;v=coalesce(a->>(f->>'key'),'');
 if (coalesce((f->>'required')::boolean,false) and v='') or length(v)>coalesce((f->>'max')::integer,250) or (v<>'' and f ? 'options' and not (f->'options' ? v)) then errs=array_append(errs,f->>'key');end if;
 if v<>'' then
 if f->>'type'='email' and v !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then errs=array_append(errs,f->>'key');end if;
 if f->>'type'='tel' and (v !~ '[0-9]' or v !~ '^[+0-9(). -]+$') then errs=array_append(errs,f->>'key');end if;
 if f->>'type'='country' and v !~ '^[A-Z]{2}$' then errs=array_append(errs,f->>'key');end if;
 if f->>'type'='number' and v !~ '^[0-9]+(\.[0-9]{1,2})?$' then errs=array_append(errs,f->>'key');end if;
 if f->>'type'='date' and (v !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or v>current_date::text) then errs=array_append(errs,f->>'key');end if;
 end if;end loop;
 if a->>'country'='EC' and ((a->>'idType'='ruc' and a->>'id' !~ '^[0-9]{13}$') or (a->>'idType'='cedula' and a->>'id' !~ '^[0-9]{10}$')) then errs=array_append(errs,'id');end if;
 if a->>'invoice'='yes' and a->>'country'='EC' and a->>'taxId' !~ '^[0-9]{13}$' then errs=array_append(errs,'taxId');end if;
 if a->>'person'='legal' then
 if jsonb_array_length(a->'owners')=0 and coalesce(a->>'ownershipExplanation','')='' then errs=array_append(errs,'ownershipExplanation');end if;
 for o in select value from jsonb_array_elements(a->'owners') loop
 if coalesce(o->>'name','')='' or coalesce(o->>'id','')='' or o->>'country' !~ '^[A-Z]{2}$' or length(o->>'name')>250 or length(o->>'id')>60 then errs=array_append(errs,'owners');end if;
 if o->>'pct' !~ '^[0-9]+(\.[0-9]{1,2})?$' then errs=array_append(errs,'owners');else
 if (o->>'pct')::numeric<10 or (o->>'pct')::numeric>100 then errs=array_append(errs,'owners');end if;total=total+(o->>'pct')::numeric;end if;
 end loop;if total>100.001 then errs=array_append(errs,'owners');end if;end if;return errs;
end;$$;
create or replace function glf_kyc_private.documents(p jsonb) returns text[] language plpgsql immutable set search_path='' as $$
declare a jsonb:=glf_kyc_private.project(p);r text[]:=array['signed','identity'];i integer;
begin
 if a->>'relation' in('staff','board') then return r||array['cv'];end if;r=r||array['tax','bank','address_doc'];
 if a->>'person'='legal' then r=r||array['appointment'];for i in 0..jsonb_array_length(a->'owners')-1 loop r=array_append(r,'owner_'||i);end loop;end if;return r;
end;$$;

create or replace function glf_kyc_private.create_base(p_supplier uuid,p_name text,p_email text,p_relation text) returns uuid language plpgsql security definer set search_path='' as $$
declare v_id uuid;s public.glf_suppliers;a jsonb;
begin
 if public.glf_kyc_allowed() is not true then raise exception 'FORBIDDEN';end if;
 if p_supplier is not null and p_relation in('staff','board') then raise exception 'INVALID_ROUTE';end if;
 if p_supplier is not null then select * into s from public.glf_suppliers where id=p_supplier and active;if not found then raise exception 'INVALID_SUPPLIER';end if;end if;
 a=jsonb_build_object('relation',p_relation,'name',trim(p_name),'email',lower(trim(p_email)),'country',coalesce(s.id_country_code,s.country_code,'EC'),'residenceCountry',coalesce(s.country_code,'EC'),'person',coalesce(s.person_type,'natural'),'id',coalesce(s.id_number,''),'idType',coalesce(s.id_type,'cedula'),'phone',coalesce(s.phone,''),'city',coalesce(s.city,''),'address',coalesce(s.address,''),'taxId',coalesce(nullif(s.tax_number,''),case when s.id_type='ruc' then s.id_number else '' end),'invoice',case when s.person_type='natural' and (s.id_type='ruc' or s.tax_number<>'') then 'yes' else '' end,'nationalityType',case when coalesce(s.country_code,'EC')='EC' then 'national' else 'international' end,'legalRep',coalesce(s.legal_rep_name,''),'activity',coalesce(s.description,''),'services',coalesce(s.description,''),'owners','[]'::jsonb);
 insert into public.glf_kyc_cases(supplier_id,name,email,relation,answers,created_by) values(p_supplier,trim(p_name),lower(trim(p_email)),p_relation,glf_kyc_private.project(a),auth.uid()) returning id into v_id;
 insert into public.glf_kyc_events(case_id,action,actor_id) values(v_id,'created',auth.uid());return v_id;
end;$$;

revoke all on all functions in schema glf_kyc_private from public,anon,authenticated;
commit;
